// Injected only into html_preview, never into the distributed prototype.
(()=>{const {d,render,controls}=prototypeUI,$=id=>document.getElementById(id),saved=JSON.parse(JSON.stringify(d)),results=[];let assertions=0;
function check(ok,message){assertions++;if(!ok)throw Error(message);}
function run(name,fn){try{fn();results.push({name,passed:true})}catch(e){results.push({name,passed:false,error:e.message});if($('modal').open)$('modal').close();d.discard();}}
function change(id,value){$(id).value=value;$(id).dispatchEvent(new Event('change',{bubbles:true}));}
function clickText(text){const b=[...$('modal').querySelectorAll('button')].find(x=>x.textContent===text);check(!!b,'Missing modal action '+text);b.click();}
run('blank → LabelledSlider → exposed API → Apply',()=>{ $('new').click();change('new-name','JourneySlider');clickText('Create blank');check(d.draft.nodes.length===0,'blank starts empty');change('insert-kind','Text');$('insert').click();change('insert-kind','Slider');$('insert').click();change('property-type','Number');$('expose').click();check(d.draft.api.value.type==='Number','numeric exposure');check(!d.catalog[d.draft.id],'draft not confirmed');$('apply').click();check(!d.dirty,'Apply confirms');check($('layers').children.length===2,'two visible layer entries');});
run('layout authoring and draft undo',()=>{change('gap','24');check(d.draft.layout.gap===24,'gap saved to draft');check($('component').style.gap==='24px','gap preview');$('undo').click();check(d.draft.layout.gap===8,'undo restores gap');change('flow','row');check($('component').style.flexDirection==='row','row preview');$('discard').click();check(d.draft.layout.flow==='column','discard restores flow');});
run('Test slider changes sample only',()=>{$('test-mode').click();const x=$('component').querySelector('input[type=range]');check(!x.disabled,'Test enabled slider');x.value='77';x.dispatchEvent(new Event('input',{bubbles:true}));check(Object.values(d.values).includes('77'),'sample captured');check(!d.dirty,'Test does not dirty source');$('edit-mode').click();check($('component').querySelector('input[type=range]').disabled,'Edit disables sample control');});
run('mode, named color outlet and reset',()=>{change('appearance','Light');check(!d.dirty,'mode preview local');change('text-color','#123456');check(d.draft.colors.Light.text==='#123456','mode color in draft');change('instance-color','#abcdef');$('override').click();check($('instance-source').textContent.includes('override'),'override provenance');$('reset').click();check($('instance-sample').style.color==='rgb(18, 52, 86)','Reset resolves changed default');$('apply').click();change('appearance','Dark');check(!d.dirty,'mode switch remains local');});
run('stale Apply reports conflict and retains draft',()=>{change('gap','20');$('simulate-remote').click();$('apply').click();check($('message').textContent.includes('stale'),'stale diagnostic');check(d.draft.layout.gap===20,'draft retained');$('rebase').click();$('apply').click();check(!d.dirty,'explicit model rebase can apply');});
for(const kind of controls)run('control render and interaction / '+kind,()=>{d.create('Browser '+kind);d.insert(kind);d.apply();d.test=true;render();const widget=$('component').querySelector('[data-kind="'+kind+'"]');check(!!widget,'widget rendered');check(widget.getBoundingClientRect().width>0,'widget has width');const x=widget.querySelector('input,select,button');if(x){check(!x.disabled,'sample enabled');if(x.tagName==='BUTTON')x.click();else if(x.tagName==='SELECT'){x.value='High';x.dispatchEvent(new Event('change',{bubbles:true}));}else{if(x.type==='checkbox')x.checked=true;else x.value=x.type==='range'?'35':x.type==='number'?'23':'Edited';x.dispatchEvent(new Event('input',{bubbles:true}));}if(kind==='Dialog'){check($('modal').open,'modal specimen opens');clickText('Cancel');}else check(Object.keys(d.values).some(k=>k===d.draft.nodes[0].id),'interaction reaches sample state');}if(x&&kind!=='Dialog')check(x.isConnected,'active control retained during interaction');check(!d.dirty,'sample did not edit source');d.test=false;render();});
run('in-use deletion modal blocks; retire prevents new use',()=>{d.create('Consumer');d.insert('LabelledSlider');d.apply();d.open('LabelledSlider');render();$('delete').click();check($('modal-body').textContent.includes('Blocked'),'impact visible');clickText('Delete definition');check($('message').textContent.includes('In use'),'delete rejected');check(!!d.catalog.LabelledSlider,'definition retained');clickText('Cancel');$('retire').click();clickText('Retire definition');check(!d.catalog.LabelledSlider.retired,'retire staged');$('apply').click();check(d.catalog.LabelledSlider.retired,'retired');check(![...$('insert-kind').options].some(x=>x.value==='LabelledSlider'),'retired absent from insert');});
run('Publish is explicit separate snapshot',()=>{$('publish').click();clickText('Snapshot confirmed model');check(d.published!==null,'snapshot produced');check($('message').textContent.includes('no external'),'simulation labeled');});
run('inspector scroll reaches lifecycle actions',()=>{render();const panel=document.querySelector('.right');panel.scrollTop=panel.scrollHeight;const target=$('delete').getBoundingClientRect(),bounds=panel.getBoundingClientRect();check(target.top>=bounds.top&&target.bottom<=bounds.bottom,'Delete reachable inside scrolling inspector');panel.scrollTop=0;});
Object.assign(d,saved);$('appearance').value=d.mode;$('profile').value='Frame';$('designer').classList.add('frame');render();requestAnimationFrame(()=>{const report={kind:'OIB_DESIGNER_BROWSER_TESTS',cases:results.length,assertions,passed:results.filter(x=>x.passed).length,failed:results.filter(x=>!x.passed),results,viewport:{width:innerWidth,height:innerHeight},shellHeight:$('designer').getBoundingClientRect().height,overflow:document.documentElement.scrollWidth>innerWidth};console.info(JSON.stringify({...report,results:undefined}));});})();
